	/**
	 *
	 * @param ci
	 * @param useWeighted
	 * @param robust
	 * @param cluster
	 * @throws Exception
	 */
	public void coxphfitSCleanup(CoxInfo ci, boolean useWeighted,boolean robust, ArrayList<String> cluster) throws Exception {
		//Do cleanup found after coxfit6 is called in coxph.fit.S
		//infs <- abs(coxfit$u %*% var)
		//[ a1 b1] * [a1 b1]
		//           [a2 b2]
		double[][] du = new double[1][ci.u.length];
		du[0] = ci.u;
		double[] infs = Matrix.abs(Matrix.multiply(ci.u, ci.getVariance()));
//        StdArrayIO.print(infs);

		ArrayList<CoxCoefficient> coxCoefficients = new ArrayList<>(ci.getCoefficientsList().values());

		for (int i = 0; i < infs.length; i++) {
			double inf = infs[i];
			double coe = coxCoefficients.get(i).getCoeff();
			if (inf > ci.eps && inf > (ci.toler * Math.abs(coe))) {
				ci.message = "Loglik converged before variable ";
			}
		}

		//sum(coef*coxfit$means)
		double sumcoefmeans = 0;
		for (CoxCoefficient cc : coxCoefficients) {
			sumcoefmeans = sumcoefmeans + cc.getCoeff() * cc.getMean();
		}

		// coxph.fit.S line 107
		//lp <- c(x %*% coef) + offset - sum(coef*coxfit$means)
		for (SurvivalInfo si : ci.survivalInfoList) {
			double offset = si.getOffset();
			double lp = 0;
			for (CoxCoefficient cc : coxCoefficients) {
				String name = cc.getName();
				double coef = cc.getCoeff();
				double value = si.getVariable(name);
				lp = lp + value * coef;
			}
			lp = lp + offset - sumcoefmeans;
			si.setLinearPredictor(lp);
			si.setScore(Math.exp(lp));

//           System.out.println("lp score " + si.order + " " + si.time + " " + si.getWeight() + " " + si.getClusterValue() + " " + lp + " " + Math.exp(lp));
		}
//       ci.dump();
		//begin code after call to coxfit6 in coxph.fit.S
		//Compute the martingale residual for a Cox model
		// appears to be C syntax error for = - vs -=
		//(if (nullmodel) in coxph.fit
		double[] res = CoxMart.process(ci.method, ci.survivalInfoList, false);

		for(int i = 0; i < ci.survivalInfoList.size(); i++){
			SurvivalInfo si = ci.survivalInfoList.get(i);
			si.setResidual(res[i]);
		}

		//this represents the end of coxph.fit.S code and we pickup
		//after call to fit <- fitter(X, Y, strats ....) in coxph.R

		if (robust) {
			ci.setNaiveVariance(ci.getVariance());
			double[][] temp;
			double[][] temp0;

			if (cluster != null) {

				temp = ResidualsCoxph.process(ci, ResidualsCoxph.Type.dfbeta, useWeighted, cluster);
				//# get score for null model
				//    if (is.null(init))
				//          fit2$linear.predictors <- 0*fit$linear.predictors
				//    else
				//          fit2$linear.predictors <- c(X %*% init)
				//Set score to 1

				double[] templp = new double[ci.survivalInfoList.size()];
				double[] tempscore = new double[ci.survivalInfoList.size()];
				int i = 0;
				for (SurvivalInfo si : ci.survivalInfoList) {
					templp[i] = si.getLinearPredictor();
					tempscore[i] = si.getScore();
					si.setLinearPredictor(0);
					si.setScore(1.0); //this erases stored value which isn't how the R code does it
					i++;
				}

				temp0 = ResidualsCoxph.process(ci, ResidualsCoxph.Type.score, useWeighted, cluster);

				i = 0;
				for (SurvivalInfo si : ci.survivalInfoList) {
					si.setLinearPredictor(templp[i]);
					si.setScore(tempscore[i]); //this erases stored value which isn't how the R code does it
					i++;
				}


			} else {
				temp = ResidualsCoxph.process(ci, ResidualsCoxph.Type.dfbeta, useWeighted, null);
				//     fit2$linear.predictors <- 0*fit$linear.predictors
				double[] templp = new double[ci.survivalInfoList.size()];
				double[] tempscore = new double[ci.survivalInfoList.size()];
				int i = 0;
				for (SurvivalInfo si : ci.survivalInfoList) {
					templp[i] = si.getLinearPredictor();
					tempscore[i] = si.getScore();
					si.setLinearPredictor(0);
					si.setScore(1.0);
				}
				temp0 = ResidualsCoxph.process(ci, ResidualsCoxph.Type.score, useWeighted, null);

				i = 0;
				for (SurvivalInfo si : ci.survivalInfoList) {
					si.setLinearPredictor(templp[i]);
					si.setScore(tempscore[i]); //this erases stored value which isn't how the R code does it
					i++;
				}
			}
			//fit$var<- t(temp) % * % temp
			double[][] ttemp = Matrix.transpose(temp);
			double[][] var = Matrix.multiply(ttemp, temp);
			ci.setVariance(var);
			//u<- apply(as.matrix(temp0), 2, sum)
			double[] u = new double[temp0[0].length];
			for (int i = 0; i < temp0[0].length; i++) {
				for (int j = 0; j < temp0.length; j++) {
					u[i] = u[i] + temp0[j][i];
				}
			}
			//fit$rscore <- coxph.wtest(t(temp0)%*%temp0, u, control$toler.chol)$test
			double[][] wtemp = Matrix.multiply(Matrix.transpose(temp0),temp0);
			double toler_chol = 1.818989e-12;
		  //  toler_chol = ci.toler;
			WaldTestInfo wti = WaldTest.process(wtemp,u,toler_chol);
			//not giving the correct value
			ci.setRscore(wti.getTest());
		}
		calculateWaldTestInfo(ci);




	}

	/**
	 *
	 * @param ci
	 * @param type
	 * @param useWeighted
	 * @param cluster
	 * @return
	 * @throws Exception
	 */
	public static double[][] process(CoxInfo ci, Type type, boolean useWeighted, ArrayList<String> cluster) throws Exception {
		Type otype = type;
		if (type == Type.dfbeta || type == Type.dfbetas) {
			type = Type.score;
			//if missing weighted is a required so never missing
		} //64 2 625 310

		double[][] rr = null;
		if (type == Type.score) {
			rr = CoxScore.process(ci.method, ci.survivalInfoList, ci, false);
		}

		//debug
//        if (false) {
//            for (int i = 0; i < ci.survivalInfoList.size(); i++) {
//                SurvivalInfo si = ci.survivalInfoList.get(i);
//                System.out.print("residuals " + si.getOrder() + " " + si.getClusterValue());
//                for (int j = 0; j < 2; j++) {
//                    System.out.print(" " + rr[i][j]);
//                }
//                System.out.println();
//            }
//        }


		double[][] vv = null;
		if (ci.getNaiveVariance() != null) {
			vv = ci.getNaiveVariance();
		} else {
			vv = ci.getVariance();
		}
		if (otype == Type.dfbeta) {
			//rr <- rr %*% vv
			rr = Matrix.multiply(rr, vv);
		} else if (otype == Type.dfbetas) {
			//rr <- (rr %*% vv) %*% diag(sqrt(1/diag(vv)))
			double[][] d1 = Matrix.multiply(rr, vv);
			double[][] d2 = Matrix.diag(Matrix.sqrt(Matrix.oneDivide(Matrix.diag(vv))));
			rr = Matrix.multiply(d1, d2);
		}



		if (useWeighted) {
			double[] weighted = ci.getWeighted();
			rr = Matrix.scale(rr, weighted);
		}
		if (cluster != null && !cluster.isEmpty()) {
			rr = rowsum(rr, cluster);
		}


		return rr;
	}

	/**
	 * From R in residuals.coxph.S rowsum(rr, collapse)
	 *
	 * @param rr
	 * @param sets
	 * @return
	 */
	private static double[][] rowsum(double[][] rr, ArrayList<String> sets) throws Exception {
		LinkedHashMap<String, Double> sumMap = new LinkedHashMap<>();
		if (rr.length != sets.size()) {
			throw new Exception("Cluster value for each sample are not of equal length n=" + rr.length + " cluster length=" + sets.size());
		}
		double[][] sum = null;
		for (int j = 0; j < rr[0].length; j++) {
			for (int i = 0; i < sets.size(); i++) {
				String s = sets.get(i);
				Double v = sumMap.get(s); //get in order
				if (v == null) {
					v = 0.0;
				}
				v = v + rr[i][j];
				sumMap.put(s, v);

			}
			if (sum == null) {
				sum = new double[sumMap.size()][rr[0].length];
			}

			ArrayList<String> index = new ArrayList<>(sumMap.keySet());
			//sorting does seem to make a difference in test cases at the .0000000001
	   //     ArrayList<Integer> in = new ArrayList<Integer>();
	   //     for (String s : index) {
	   //         in.add(Integer.parseInt(s));
	   //     }
	   //     Collections.sort(index);

			for (int m = 0; m < index.size(); m++) {
				String key = index.get(m);
				sum[m][j] = sumMap.get(key);
			}

			sumMap.clear();
		}

		return sum;

public class SurvivalInfo implements Comparable<SurvivalInfo> {

	private String id = "";
	private double time;
	private int status;
	private int order = 0; //not really used but included to keep track of original position if sorting.
	private double offset = 0; //offsets for linear predictor ????
	private double weight = 1; //used to set weight of survivor for over sampling.
	private int strata = 0; // this should be a boolean but leaving as an int
	private double score = 0.0;
	private double linearPredictor = 0.0;
	private double residual = 0.0;
	private String clusterValue = "";

	LinkedHashMap<String,Double> residualVariableMap = new LinkedHashMap<>();

	LinkedHashMap<String, Double> data = new LinkedHashMap<>();
	//    LinkedHashMap<String, Double> discreteData = new LinkedHashMap<String, Double>();
	LinkedHashMap<String, String> unknownDataType = new LinkedHashMap<>();
	LinkedHashMap<String, String> originalMetaData = new LinkedHashMap<>();

	/**
	 *
	 * @param t
	 * @param e
	 */
	public SurvivalInfo(double t, int e) {
		time = t;
		status = e;

	}

	/**
	 *
	 * @param t
	 * @param e
	 * @param d
	 */
	public SurvivalInfo(double t, int e, LinkedHashMap<String, Double> d) {
		time = t;
		status = e;

		data = d;
		for(String key : d.keySet()){
			Double value = d.get(key);
			originalMetaData.put(key, value + "");
		}
	}

@Override
public int compareTo(SurvivalInfo o) {
	//    return (int) (this.time - o.time - (this.status - o.status) / 1024);
	if (time < o.time) {
		return -1;
	} else if (time > o.time) {
		return 1;
	} else {
		if (this.status == o.status) {
			return 0;
		} else if (status == 1) {
			return -1;
		} else {
			return 1;
		}
	}

package dk.alexandra.fresco.stat.survival;

import dk.alexandra.fresco.framework.DRes;
import dk.alexandra.fresco.framework.util.Pair;
import dk.alexandra.fresco.framework.value.SInt;
import dk.alexandra.fresco.lib.fixed.SFixed;
import java.util.ArrayList;
import java.util.List;

/**
 * Represents a data entry in data for survival analysis with continuous covariates.
 */
public class SurvivalEntry implements DRes<SurvivalEntry> {

  private final List<DRes<SFixed>> covariates;
  private final DRes<SInt> time;
  private final DRes<SInt> censored;

  public SurvivalEntry(List<DRes<SFixed>> covariates, DRes<SInt> time,
      DRes<SInt> censored) {
    this.covariates = covariates;
    this.time = time;
    this.censored = censored;
  }

  /**
   * Encode an entry in a survival analysis dataset as a key-value pair where the event time is the
   * key and the status and covariates are the value. This may be decoded using {@link
   * SurvivalEntry#decode(Pair)} method.
   */
  public static Pair<DRes<SInt>, List<DRes<SInt>>> encode(SurvivalEntry subject) {
    List<DRes<SInt>> row = new ArrayList<>();

    row.add(subject.getCensored());

    for (DRes<SFixed> covariate : subject.getCovariates()) {
      row.add(covariate.out().getSInt());
    }

    return new Pair<>(subject.getTime(), row);
  }

  /**
   * Decode a key-value pair encoded using the {@link dk.alexandra.fresco.stat.survival.SurvivalEntry#encode(dk.alexandra.fresco.stat.survival.SurvivalEntry)}
   * method
   */
  public static SurvivalEntry decode(Pair<DRes<SInt>, List<DRes<SInt>>> subject) {
    DRes<SInt> censored = subject.getSecond().get(0);
    DRes<SInt> time = subject.getFirst();

    List<DRes<SFixed>> covariates = new ArrayList<>();
    for (int i = 1; i < subject.getSecond().size(); i++) {
      covariates
          .add(new SFixed(subject.getSecond().get(i)));
    }
    return new SurvivalEntry(covariates, time, censored);
  }

  public List<DRes<SFixed>> getCovariates() {
    return covariates;
  }

  public DRes<SInt> getTime() {
    return time;
  }

  public DRes<SInt> getCensored() {
    return censored;
  }

  @Override
  public SurvivalEntry out() {
    return this;
  }
}

