  @Override
  public DRes<Pair<List<SurvivalEntry>, List<BigInteger>>> buildComputation(
      ProtocolBuilderNumeric builder) {

    return builder.seq(seq -> {

      List<Pair<DRes<SInt>, List<DRes<SInt>>>> values =
          data.stream().map(this::encode).collect(Collectors.toList());
      return dk.alexandra.fresco.lib.common.collections.Collections.using(seq).sort(values);

    }).seq((seq, sorted) -> {
      List<SurvivalEntry> sortedData = sorted.stream().map(this::decode)
          .collect(Collectors.toList());

      // Find ties
      DRes<List<BigInteger>> tiedGroups = new FindTiedGroups(
          VectorUtils.listBuilder(sortedData.size(), i -> sorted.get(i).getFirst()))
          .buildComputation(seq);
      return Pair.lazy(sortedData, tiedGroups);

    }).seq((seq, result) -> Pair.lazy(result.getFirst(), result.getSecond().out()));
  }
}

            .map(xj -> AdvancedFixedNumeric.using(par).innerProduct(xj.getCovariates(), beta))
            .collect(
                Collectors.toList());
        return state;
      }).par((par, state) -> {

    // compute theta_j = exp(x_j . beta) for all data entries j
    state.thetas = state.innerProducts.stream().map(AdvancedFixedNumeric.using(par)::exp).collect(
        Collectors.toList());
    return state;

  }).par((par, state) -> {

    // Compute theta_j * x_j
    state.sum1terms = IntStream.range(0, n).mapToObj(
        j -> VectorUtils.scale(data.get(j).getCovariates(), state.thetas.get(j), par)
    ).collect(Collectors.toList());
    return state;

  }).pairInPar((seq, state) -> {

    // Compute accumulated sums of theta_j * x_j's and theta_j's
    state.sum1.add(state.sum1terms.get(0));
    for (int j = 1; j < state.sum1terms.size(); j++) {
      state.sum1.add(VectorUtils.add(state.sum1.get(j - 1), state.sum1terms.get(j), seq));
    }
    return state;

  }, (seq, state) -> {

    state.sum2.add(state.thetas.get(0));
    for (int j = 1; j < state.thetas.size(); j++) {
      state.sum2.add(FixedNumeric.using(seq).add(state.sum2.get(j - 1), state.thetas.get(j)));
    }
    return state;

  }).par((par, statePair) -> {

    // The parallel scopes above are changing the same object
    State state = statePair.getFirst();

    // Correct for ties -- does not require MPC computation
    for (int j = n - 2; j >= 0; j--) {
      if (tiedGroups.get(j).equals(tiedGroups.get(j + 1))) {
        state.sum1.set(j, state.sum1.get(j + 1));
        state.sum2.set(j, state.sum2.get(j + 1));
      }
    }

    // Sum2 is only used for division so we compute the reciprocal
    state.sum2recip = state.sum2.stream().map(AdvancedFixedNumeric.using(par)::reciprocal)
        .collect(
            Collectors.toList());
    return state;

  }).par((par, state) -> {

    // Compute ratios of sum1 and sum2
    state.ratios = IntStream.range(0, n)
        .mapToObj(j -> VectorUtils.scale(state.sum1.get(j), state.sum2recip.get(j), par))
        .collect(
            Collectors
                .toList());
    return state;
  }).par((par, state) -> {

    // The terms in the final sum are x_j - ratio_j
    state.terms = IntStream.range(0, n)
        .mapToObj(j -> VectorUtils.sub(data.get(j).getCovariates(), state.ratios.get(j), par))
        .collect(
            Collectors.toList());
    return state;

  }).par((par, state) -> {

    // Only include terms with status = 1
    List<DRes<SInt>> status = VectorUtils
        .listBuilder(n, j -> data.get(j).getCensored());
    state.result = VectorUtils
        .listBuilder(beta.size(), i -> VectorUtils.innerProductWithBitvector(
            status,
            // The i'th entries in the terms
            VectorUtils.listBuilder(n, j -> state.terms.get(j).get(i)),
            par));
    return state;

  });
}

// Reused in CoxHessianInternal
static class State implements DRes<State> {

// Maximise the score function of a cox model
public class CoxOptimiser implements Computation<List<DRes<SFixed>>, ProtocolBuilderNumeric> {

  private final List<DRes<SFixed>> init;
  private final int iterations;
  private final double stepSize;
  private final Function<List<DRes<SFixed>>, CoxGradient.CoxGradientInternal> gradient;
  private final BiFunction<List<DRes<SFixed>>, CoxGradient.CoxGradientInternal.State, CoxHessian.CoxHessianInternal> hessian;

  public CoxOptimiser(List<SurvivalEntry> data, List<BigInteger> tiedGroups,
      List<DRes<SFixed>> init,
      int iterations, double stepSize) {
    this.init = init;
    this.iterations = iterations;
    this.stepSize = stepSize;
    this.gradient = b -> new CoxGradient.CoxGradientInternal(data, tiedGroups, b);

    // The computation of the Hessian reuses some of the intermediate values from the computation of the gradient (the "state" parameter)
    this.hessian = (b, state) -> new CoxHessian.CoxHessianInternal(data, tiedGroups, b, state);
  }

  @Override
  public DRes<List<DRes<SFixed>>> buildComputation(ProtocolBuilderNumeric builder) {
    return builder.seq(seq -> new State(init, 0)).whileLoop(
        state -> state.iteration < iterations, (root, state) -> root.seq(seq -> {

          // Compute the gradient
          return gradient.apply(state.beta).buildComputation(seq);

        }).seq((seq, g) -> {

          // The computation of the Hessian reuses some of the intermediate values from the computation of the gradient
          DRes<CoxHessian.CoxHessianInternal.State> h = hessian.apply(state.beta, g.out()).buildComputation(seq);
          return Pair.lazy(g.out().result, h);

        }).seq((seq, gradientAndHessian) -> {

          // Compute the (pseudo)inverse of the Hessian
          DRes<Matrix<DRes<SFixed>>> hessianInverse =
              AdvancedLinearAlgebra.using(seq)
                  .moorePenrosePseudoInverse(gradientAndHessian.getSecond().out().hessian.out());
          return Pair.lazy(gradientAndHessian.getFirst(), hessianInverse);

        }).seq((seq, gradientAndHessianInverse) -> FixedLinearAlgebra.using(seq)
            .vectorMult(gradientAndHessianInverse.getSecond(),
                DRes.of(gradientAndHessianInverse.getFirst()))
        ).seq((seq, delta) -> {

          // Iterate, x_{i+1} = x_i + G * H^{-1} (Newton's method)
          List<DRes<SFixed>> deltaScaled = VectorUtils.scale(delta, stepSize, seq);
          List<DRes<SFixed>> beta = VectorUtils.sub(state.beta, deltaScaled, seq);
          return new State(beta, state.iteration + 1);

        })).seq((seq, state) -> DRes.of(state.beta));
  }

  private static class State implements DRes<State> {

    private final List<DRes<SFixed>> beta;
    private final int iteration;

    private State(List<DRes<SFixed>> beta, int iteration) {
      this.beta = beta;
      this.iteration = iteration;
    }

    @Override
    public State out() {
      return this;
    }
  }
}

 * Estimate the coefficients of a Cox proportional hazards model on the given data using gradient
 * descent.
 */
public class CoxRegression implements
    Computation<CoxRegression.CoxRegressionResult, ProtocolBuilderNumeric> {

  private final int iterations;
  private final double alpha;
  private final double[] beta;
  private final SurvivalEntrySorter sorter;
  private List<BigInteger> tiedGroups;
  private List<SurvivalEntry> sortedData;

  /**
   * Estimate the coefficients of a Cox model on the given data using gradient descent.
   *
   * @param data       The data.
   * @param iterations The number of iterations.
   * @param alpha      The learning rate.
   */
  public CoxRegression(List<SurvivalEntry> data, int iterations, double alpha,
      double[] beta) {
    this.iterations = iterations;
    this.alpha = alpha;
    this.beta = beta;
    this.sorter = new SurvivalEntrySorter(data);
  }

  @Override
  public DRes<CoxRegressionResult> buildComputation(ProtocolBuilderNumeric builder) {

    return builder.seq(sorter).par((par, sorted) -> {

      this.tiedGroups = sorted.getSecond();
      this.sortedData = sorted.getFirst();

      FixedNumeric numeric = FixedNumeric.using(par);
      List<DRes<SFixed>> initialBeta = Arrays.stream(beta).mapToObj(numeric::known)
          .collect(
              Collectors.toList());
      return DRes.of(initialBeta);

    }).seq((seq, init) ->

        seq.seq(new CoxOptimiser(sortedData, tiedGroups, init, iterations, alpha))

    ).seq((seq, beta) -> {

      DRes<State> hessianState = seq
          .seq(new CoxHessian.CoxHessianInternal(sortedData, tiedGroups, beta));
      return Pair.lazy(beta, hessianState);

    }).par((par, betaAndHessianState) -> {

      DRes<Matrix<DRes<SFixed>>> hInverse = AdvancedLinearAlgebra.using(par)
          .moorePenrosePseudoInverse(betaAndHessianState.getSecond().out().hessian.out());

      DRes<SFixed> G = new CoxPartialLikelihoodRatioTest(sortedData, tiedGroups,
          betaAndHessianState.getFirst(), betaAndHessianState.getSecond().out())
          .buildComputation(par);

      return DRes.of(new Triple<>(betaAndHessianState.getFirst(), hInverse, G));

    }).seq((seq, betaAndHInverseAndG) -> {

      List<DRes<SFixed>> errors = IntStream.range(0, beta.length)
          .mapToObj(i -> betaAndHInverseAndG.getSecond().out().getRow(i).get(i)).map(xii ->
              seq.seq(b -> AdvancedFixedNumeric.using(b).sqrt(FixedNumeric.using(b).sub(0, xii)))
          ).collect(Collectors.toList());

      return new CoxRegressionResult(betaAndHInverseAndG.getFirst(), betaAndHInverseAndG.getThird(),
          errors);

    });

  }

  public static class CoxRegressionResult implements DRes<CoxRegressionResult> {

    private final DRes<SFixed> G;
    private final List<DRes<SFixed>> model;
    private final List<DRes<SFixed>> standardErrors;

    CoxRegressionResult(List<DRes<SFixed>> model, DRes<SFixed> G,
        List<DRes<SFixed>> standardErrors) {
      this.model = model;
      this.G = G;
      this.standardErrors = standardErrors;
    }

    public List<DRes<SFixed>> getModel() {
      return model;
    }

    public List<DRes<SFixed>> getStandardErrors() {
      return standardErrors;
    }

    public DRes<SFixed> getPartialLikelihoodRatioTest() {
      return G;
    }

    @Override
    public CoxRegressionResult out() {
      return this;
    }
  }
}

